```javascript
const fs = require('fs');

const [V, A, F, P] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const bills = [A, F, P].sort((a, b) => a - b);

let remaining = V;
let count = 0;

for (const bill of bills) {
  if (bill > remaining) break;
  remaining -= bill;
  count++;
}

console.log(count);
